export function generateIgnoreContent(detectedStacks: DetectedStack[]): string {
  const lines: string[] = [...UNIVERSAL_IGNORE_PATTERNS, ''];

  const stackIds = new Set<StackId>(detectedStacks.map((s) => s.id));
  if (stackIds.size === 0) {
    // Include common defaults if empty project
    stackIds.add('node-ts');
    stackIds.add('python');
  }

  for (const id of stackIds) {
    const patterns = STACK_SPECIFIC_PATTERNS[id];
    if (patterns) {
      lines.push(...patterns, '');
    }
  }

  lines.push('# --- Custom Project Exclusions (Add yours below) ---');
  lines.push('# docs/archive/');
  lines.push('# fixtures/');
  lines.push('');

  return lines.join('\n');
}

export class IgnoreMatcher {
  private dirNames = new Set<string>([
    '.git',
    '.svn',
    '.hg',
    'node_modules',
    'dist',
    'build',
    'out',
    'coverage',
    '.next',
    '.nuxt',
    '.svelte-kit',
    '.astro',
    '.turbo',
    '.vercel',
    '.cache',
    '__pycache__',
    '.venv',
    'venv',
    '.pytest_cache',
    '.mypy_cache',
    '.ruff_cache',
    'target',
    'vendor',
    '.gradle',
    '.idea',
    '.vscode',
    'lua_modules',
    'obj',
    '.vs',
  ]);

  private exactFileNames = new Set<string>([
    'package-lock.json',
    'pnpm-lock.yaml',
    'yarn.lock',
    'bun.lockb',
    'bun.lock',
    'poetry.lock',
    'Pipfile.lock',
    'uv.lock',
    'Cargo.lock',
    'go.sum',
    'composer.lock',
    'Gemfile.lock',
    'packages.lock.json',
    '.DS_Store',
    'Thumbs.db',
    'REPO_MAP.md',
    'CONTEXT_STATE.md',
    '.claudeignore',
    '.antigravityignore',
    '.aiignore',
  ]);

  private regexRules: { regex: RegExp; negated: boolean }[] = [];

  constructor(cwd: string) {
    const ignoreFiles = ['.gitignore', '.aiignore', '.claudeignore', '.antigravityignore'];
    for (const file of ignoreFiles) {
      const fullPath = path.join(cwd, file);
      if (fs.existsSync(fullPath)) {
        try {
          const content = fs.readFileSync(fullPath, 'utf8');
          this.addRulesFromContent(content);
        } catch {
          // Ignore read errors
        }
      }
    }

    // Also add default bloat extensions so even before `init` is run, stats/map recognizes bloat
    this.addRulesFromContent(
      [
        '*.min.js',
        '*.min.css',
        '*.bundle.js',
        '*.map',
        '*.tsbuildinfo',
        '*.log',
        '*.sqlite',
        '*.sqlite3',
        '*.db',
        '*.png',
        '*.jpg',
        '*.jpeg',
        '*.gif',
        '*.webp',
        '*.ico',
        '*.svg',
        '*.mp4',
        '*.mp3',
        '*.wav',
        '*.pdf',
        '*.zip',
        '*.tar',
        '*.gz',
        '*.woff',
        '*.woff2',
        '*.ttf',
        '*.eot',
        '*.exe',
        '*.dll',
        '*.so',
        '*.dylib',
        '*.wasm',
        '*.pyc',
        '*.pyo',
        '*.class',
        '*.jar',
        '*.luac',
      ].join('\n')
    );
  }

  private addRulesFromContent(content: string): void {
    const lines = content.split(/\r?\n/);
    for (const rawLine of lines) {
      let line = rawLine.trim();
      if (!line || line.startsWith('#')) continue;

      let negated = false;
      if (line.startsWith('!')) {
        negated = true;
        line = line.slice(1).trim();
      }
      if (!line) continue;

      if (line.endsWith('/') && !line.includes('*')) {
        const cleanDir = line.replace(/^\/+|\/+$/g, '');
        if (!cleanDir.includes('/') && !negated) {
          this.dirNames.add(cleanDir);
          continue;
        }
      }

      if (!line.includes('/') && !line.includes('*') && !line.includes('?') && !negated) {
        this.exactFileNames.add(line);
        continue;
      }

      const regex = globToRegExp(line);
      this.regexRules.push({ regex, negated });
    }
  }

  public isIgnored(relativePath: string, isDirectory: boolean = false): boolean {
    const normalized = relativePath.replace(/\\/g, '/').replace(/^\/+/, '');
    if (!normalized) return false;

    const segments = normalized.split('/');
    for (let i = 0; i < segments.length - (isDirectory ? 0 : 1); i++) {
      if (this.dirNames.has(segments[i])) {
        return true;
      }
    }

    const baseName = segments[segments.length - 1];
    if (isDirectory && this.dirNames.has(baseName)) {
      return true;
    }
    if (!isDirectory && this.exactFileNames.has(baseName)) {
      return true;
    }

    let ignored = false;
    for (const rule of this.regexRules) {
      if (rule.regex.test(normalized) || rule.regex.test(baseName)) {
        ignored = !rule.negated;
      }
    }

    return ignored;
  }
}

function globToRegExp(glob: string): RegExp {
  let pattern = glob.replace(/\\/g, '/').replace(/^\/+/, '');
  const isDirOnly = pattern.endsWith('/');
  if (isDirOnly) {
    pattern = pattern.slice(0, -1);
  }

  let regexStr = '';
  let i = 0;
  while (i < pattern.length) {
    const ch = pattern[i];
    if (ch === '*') {
      if (pattern[i + 1] === '*') {
        regexStr += '.*';
        i += 2;
        if (pattern[i] === '/') i++;
        continue;
      } else {
        regexStr += '[^/]*';
      }
    } else if (ch === '?') {
      regexStr += '[^/]';
    } else if ('.+^${}()|[]\\'.includes(ch)) {
      regexStr += '\\' + ch;
    } else {
      regexStr += ch;
    }
    i++;
  }

  if (pattern.includes('/')) {
    return new RegExp(`^${regexStr}(?:/.*)?$`, 'i');
  }
  return new RegExp(`(?:^|/)${regexStr}(?:/.*)?$`, 'i');
}
